def fv(v, d=None):
    try:
        x = float(v)
        if math.isnan(x) or math.isinf(x):
            return d
        return x
    except Exception:
        return d

def jl(v):
    if isinstance(v, dict):
        return dict(v)
    if not v:
        return {}
    try:
        q = json.loads(str(v))
        return q if isinstance(q, dict) else {}
    except Exception:
        return {}

