def c7_info(sid):
    q = feat.get(str(sid)) or {}
    vals = [q.get("c7_rsi_delta"),q.get("c7_live_gain"),q.get("c7_gap"),
            q.get("c7_slope"),q.get("entry"),q.get("trigger")]
    complete = all(v is not None for v in vals) and (q.get("trigger") or 0) > 0
    jump = ((q["entry"]/q["trigger"])-1)*100 if complete else None
    hit = bool(
        complete and
        q["c7_rsi_delta"] <= 1.5 and
        q["c7_live_gain"] >= 0.5 and
        q["c7_gap"] <= 1.0 and
        q["c7_slope"] >= 0.3 and
        jump >= 0.5
    )
    return {
        "complete":complete,"hit":hit,"jump":jump,
        "rsi_delta":q.get("c7_rsi_delta"),"live_gain":q.get("c7_live_gain"),
        "gap":q.get("c7_gap"),"slope":q.get("c7_slope"),
        "source":q.get("source"),
    }

def c8_info(sid):
    q = feat.get(str(sid)) or {}
    w = q.get("c8_watch")
    f = q.get("c8_final")
    complete = (w is not None and f is not None)
    delta = (f-w) if complete else None
    hit = bool(complete and w >= 87.7 and delta <= -3.89)
    return {
        "complete":complete,"hit":hit,"watch_score":w,
        "final_score":f,"score_delta":delta,"source":q.get("source"),
    }

# ------------------------------------------------------------------
# Daily final-candidate breadth and onset.
# Exact old C6 research definition:
# low20_streak 1 or 2 == narrow-breadth onset day 1-2.
# ------------------------------------------------------------------
def build_daily_breadth():
    rec = []
    for d,p in ((ja,"JA"),(se,"SE")):
        for _,r in d.iterrows():
            if not pre(r,p) or blocked(r,p):
                continue
            rec.append({
                "setup_id":str(r["setup_id"]),
                "symbol":str(r["symbol"]),
                "day":str(r["entry_time_kst"])[:10],
            })
    e = pd.DataFrame(rec)
    daily = e.groupby("day").agg(
        eligible_candidates=("setup_id","count"),
        breadth=("symbol","nunique"),
    ).reset_index()
    daily["day_dt"] = pd.to_datetime(daily.day)
    cal = pd.DataFrame({
        "day_dt":pd.date_range(daily.day_dt.min(),daily.day_dt.max(),freq="D")
    })
    daily = cal.merge(daily,on="day_dt",how="left")
    daily["eligible_candidates"] = daily.eligible_candidates.fillna(0)
    daily["breadth"] = daily.breadth.fillna(0)
    daily["day"] = daily.day_dt.dt.strftime("%Y-%m-%d")
    daily["low20"] = daily.breadth <= 20
    st=[]; n=0
    for v in daily.low20:
        n = n+1 if bool(v) else 0
        st.append(n)
    daily["low20_streak"] = st
    return daily

daily = build_daily_breadth()
day_meta = {
    str(r.day):{"breadth":int(r.breadth),"streak":int(r.low20_streak)}
    for r in daily.itertuples(index=False)
}
print("DAILY BREADTH BUILT",len(daily),"days",flush=True)

# ------------------------------------------------------------------
# 60m public-market data store.
# Reads the already existing Jan-Aug historical cache first.
# Missing monthly data is fetched only from Bybit public market endpoint.
# ------------------------------------------------------------------
class Market60:
    BASE_K = "https://api.bybit.com/v5/market/kline"
    BASE_I = "https://api.bybit.com/v5/market/instruments-info"

    def __init__(self):
        self.new_cache = R / ".c6_dynamic_market60_cache"
        self.new_cache.mkdir(exist_ok=True)
        self.index = defaultdict(list)
        self.hist_index = defaultdict(list)
        self.mem = OrderedDict()
        self.mem_max = 900
        self.breadth_cache = {}
        self.api_count = 0
        self._index_existing()
        self.hist_universe = self._load_hist_universe()
        self.universe = self._load_universe()
        print("MARKET60 INDEX files",sum(len(v) for v in self.index.values()),
              "symbols",len(self.index),
              "HIST_CACHE_ALT_UNIVERSE",len(self.hist_universe),
              "CURRENT_ALT_UNIVERSE",len(self.universe),flush=True)

    @staticmethod
    def _safe(s):
        return "".join(c for c in str(s) if c.isalnum() or c in "_-.")[:80]

    def _http_json(self,url,retries=6):
        last=None
        for k in range(retries):
            try:
                req=urllib.request.Request(url,headers={"User-Agent":"HJ-DYNC6-V4/1.0"})
                with urllib.request.urlopen(req,timeout=30) as resp:
                    q=json.loads(resp.read().decode("utf-8"))
                if int(q.get("retCode",-1)) != 0:
                    raise RuntimeError(f"{q.get('retCode')} {q.get('retMsg')}")
                return q
            except Exception as e:
                last=e
                time.sleep(0.5*(k+1))
        raise RuntimeError(f"HTTP FAIL {last}")

    def _load_hist_universe(self):
        """
        Jan-Aug C6 research used the original historical 60m cache universe,
        not the October current-instruments universe.
        Screenshot/audit at research time: cache symbols ~=583 total.
        BTC/ETH are market references, so exclude them from alt breadth.
        """
        root = R / ".janaug_hist_cache_v1"
        pat = re.compile(r"^(?P<sym>.+)_60_(?P<s>\d{10})_(?P<e>\d{10})\.csv\.gz$")
        out = set()
        if root.exists():
            for p in root.glob("*_60_*.csv.gz"):
                m = pat.match(p.name)
                if not m:
                    continue
                s = str(m.group("sym") or "")
                if s and s not in ("BTCUSDT","ETHUSDT"):
                    out.add(s)
        return sorted(out)

    def _load_universe(self):
        out={}
        cur=""
        while True:
            params={"category":"linear","limit":1000}
            if cur:
                params["cursor"]=cur
            q=self._http_json(self.BASE_I+"?"+urllib.parse.urlencode(params))
            res=q.get("result",{})
            for x in res.get("list",[]) or []:
                if (x.get("quoteCoin")=="USDT"
                    and x.get("contractType")=="LinearPerpetual"
                    and x.get("status")=="Trading"):
                    s=str(x.get("symbol") or "")
                    if s and s not in ("BTCUSDT","ETHUSDT"):
                        out[s]=1
            cur=str(res.get("nextPageCursor") or "")
            if not cur:
                break
        return sorted(out)

    def _index_existing(self):
        pat=re.compile(r"^(?P<sym>.+)_60_(?P<s>\d{10})_(?P<e>\d{10})\.csv\.gz$")
        hist_root=R/".janaug_hist_cache_v1"
        roots=[
            hist_root,
            self.new_cache,
            Path("/tmp"),
        ]
        seen=set()
        for root in roots:
            if not root.exists():
                continue
            iterator = root.rglob("*_60_*.csv.gz") if root == Path("/tmp") else root.glob("*_60_*.csv.gz")
            for p in iterator:
                if p in seen:
                    continue
                seen.add(p)
                m=pat.match(p.name)
                if not m:
                    continue
                try:
                    s=pd.to_datetime(m.group("s"),format="%Y%m%d%H",utc=True)
                    e=pd.to_datetime(m.group("e"),format="%Y%m%d%H",utc=True)
                    sym=m.group("sym")
                    self.index[sym].append((s,e,p))
                    # Critical: ONLY files physically inside the original
                    # Jan-Aug historical cache are allowed into hist_index.
                    if root == hist_root:
                        self.hist_index[sym].append((s,e,p))
                except Exception:
                    pass
        for sym in self.index:
            self.index[sym].sort(key=lambda x:x[0])
        for sym in self.hist_index:
            self.hist_index[sym].sort(key=lambda x:x[0])

    def _remember(self,key,df):
        if key in self.mem:
            self.mem.pop(key,None)
        self.mem[key]=df
        while len(self.mem)>self.mem_max:
            self.mem.popitem(last=False)
        return df

    def _read(self,p):
        key=str(p)
        if key in self.mem:
            df=self.mem.pop(key)
            self.mem[key]=df
            return df
        try:
            df=pd.read_csv(p,compression="gzip")
            if "start_time" in df.columns:
                df["start_time"]=pd.to_datetime(df["start_time"],utc=True)
            elif "ts" in df.columns:
                x=pd.to_numeric(df["ts"],errors="coerce")
                if x.dropna().median()>1e12:
                    df["start_time"]=pd.to_datetime(x,unit="ms",utc=True)
                else:
                    df["start_time"]=pd.to_datetime(df["ts"],utc=True,errors="coerce")
            else:
                return pd.DataFrame()
            for c in ("open","high","low","close","volume","turnover"):
                if c in df.columns:
                    df[c]=pd.to_numeric(df[c],errors="coerce")
            df=df.dropna(subset=["start_time"]).sort_values("start_time")
            return self._remember(key,df)
        except Exception:
            return pd.DataFrame()

    def _month_bounds(self,t):
        t=pd.Timestamp(t).tz_convert("UTC")
        ms=t.to_period("M").start_time.tz_localize("UTC")
        me=(ms+pd.offsets.MonthBegin(1))
        return ms-pd.Timedelta(days=3), me+pd.Timedelta(days=1)

    def _fetch_month(self,sym,t):
        st,en=self._month_bounds(t)
        p=self.new_cache/f"{self._safe(sym)}_60_{st.strftime('%Y%m%d%H')}_{en.strftime('%Y%m%d%H')}.csv.gz"
        if p.exists() and p.stat().st_size>50:
            return p
        start_ms=int(st.timestamp()*1000)
        end_ms=int((en-pd.Timedelta(milliseconds=1)).timestamp()*1000)
        params={
            "category":"linear","symbol":sym,"interval":"60",
            "start":start_ms,"end":end_ms,"limit":1000,
        }
        q=self._http_json(self.BASE_K+"?"+urllib.parse.urlencode(params))
        arr=q.get("result",{}).get("list",[]) or []
        cols=["ts","open","high","low","close","volume","turnover"]
        df=pd.DataFrame(arr,columns=cols if arr else cols)
        if len(df):
            for c in ("open","high","low","close","volume","turnover"):
                df[c]=pd.to_numeric(df[c],errors="coerce")
            df["ts"]=pd.to_numeric(df["ts"],errors="coerce")
            df["start_time"]=pd.to_datetime(df["ts"],unit="ms",utc=True)
            df=df.sort_values("start_time").drop_duplicates("start_time")
        else:
            df["start_time"]=pd.to_datetime(pd.Series([],dtype="datetime64[ns, UTC]"))
        df.to_csv(p,index=False,compression="gzip")
        self.api_count+=1
        self.index[sym].append((st,en,p))
        self.index[sym].sort(key=lambda x:x[0])
        if self.api_count%100==0:
            print("PUBLIC 60m fetches",self.api_count,flush=True)
        time.sleep(0.03)
        return p

    def frame(self,sym,t):
        t=pd.Timestamp(t).tz_convert("UTC")
        need_s=t.floor("h")-pd.Timedelta(hours=52)
        need_e=t.floor("h")+pd.Timedelta(hours=2)
        paths=[]
        for s,e,p in self.index.get(sym,[]):
            if e>=need_s and s<=need_e:
                paths.append(p)
        frames=[self._read(p) for p in paths]
        z=[x for x in frames if len(x)]
        if z:
            df=pd.concat(z,ignore_index=True).drop_duplicates("start_time").sort_values("start_time")
            have_before=(df.start_time<=need_s+pd.Timedelta(hours=3)).any()
            have_after=(df.start_time>=t.floor("h")-pd.Timedelta(hours=1)).any()
            if have_before and have_after:
                return df
        p=self._fetch_month(sym,t)
        df=self._read(p)
        return df

    def frame_hist(self,sym,t):
        """
        Strict original Jan-Aug cache only.
        Never backfill a missing month/symbol from the public API, because the
        original C6 breadth research used the cache universe that existed for
        that historical month.
        """
        t=pd.Timestamp(t).tz_convert("UTC")
        need_s=t.floor("h")-pd.Timedelta(hours=52)
        need_e=t.floor("h")+pd.Timedelta(hours=2)
        paths=[]
        for s,e,p in self.hist_index.get(sym,[]):
            if e>=need_s and s<=need_e:
                paths.append(p)
        frames=[self._read(p) for p in paths]
        z=[x for x in frames if len(x)]
        if not z:
            return pd.DataFrame()
        df=pd.concat(z,ignore_index=True).drop_duplicates("start_time").sort_values("start_time")
        have_before=(df.start_time<=need_s+pd.Timedelta(hours=3)).any()
        have_after=(df.start_time>=t.floor("h")-pd.Timedelta(hours=1)).any()
        if not (have_before and have_after):
            return pd.DataFrame()
        return df

    @staticmethod
    def _select(df,t,align):
        if df is None or len(df)==0:
            return None
        b=pd.Timestamp(t).tz_convert("UTC").floor("h")
        z=df[df.start_time < b] if align=="prev" else df[df.start_time <= b]
        if len(z)==0:
            return None
        return z.iloc[-1]

    def symbol_metrics(self,sym,t,entry_price,mode,hist_only=False):
        source,align=mode.split("_")
        df=self.frame_hist(sym,t) if hist_only else self.frame(sym,t)
        if df is None or len(df)==0:
            return None
        currow=self._select(df,t,align)
        p24row=self._select(df,pd.Timestamp(t)-pd.Timedelta(hours=24),align)
        if currow is None or p24row is None:
            return None
        if source=="entry":
            cur=fv(entry_price)
        else:
            cur=fv(currow.get("close"))
        p24=fv(p24row.get("close"))
        if cur is None or p24 is None or cur<=0 or p24<=0:
            return None
        b=pd.Timestamp(t).tz_convert("UTC").floor("h")
        hist=df[df.start_time < b] if align=="prev" else df[df.start_time <= b]
        hist=hist.tail(24)
        if len(hist)<20:
            return None
        hi=pd.to_numeric(hist["high"],errors="coerce").max()
        lo=pd.to_numeric(hist["low"],errors="coerce").min()
        if not (hi>lo>0):
            return None
        r24=(cur/p24-1)*100
        pos=(cur-lo)/(hi-lo)
        return {"r24":float(r24),"pos24":float(pos),
                "dist_high24":float((cur/hi-1)*100)}

    def true_breadth(self,t,align,universe_kind="current"):
        b=pd.Timestamp(t).tz_convert("UTC").floor("h")
        key=(b.isoformat(),align,universe_kind)
        if key in self.breadth_cache:
            return self.breadth_cache[key]
        universe = self.hist_universe if universe_kind=="hist" else self.universe
        now_yes=0; now_n=0; prev_yes=0; prev_n=0
        for i,sym in enumerate(universe,1):
            try:
                df=self.frame_hist(sym,b) if universe_kind=="hist" else self.frame(sym,b)
                a=self._select(df,b,align)
                p24=self._select(df,b-pd.Timedelta(hours=24),align)
                p48=self._select(df,b-pd.Timedelta(hours=48),align)
                c0=fv(a.get("close")) if a is not None else None
                c24=fv(p24.get("close")) if p24 is not None else None
                c48=fv(p48.get("close")) if p48 is not None else None
                if c0 and c24 and c0>0 and c24>0:
                    now_n+=1
                    if c0>c24:
                        now_yes+=1
                if c24 and c48 and c24>0 and c48>0:
                    prev_n+=1
                    if c24>c48:
                        prev_yes+=1
            except Exception:
                pass
        now_up=100*now_yes/now_n if now_n else None
        prev_up=100*prev_yes/prev_n if prev_n else None
        delta=(now_up-prev_up) if now_up is not None and prev_up is not None else None
        q={"now_up24":now_up,"now_n":now_n,"prev_up24":prev_up,
           "prev_n":prev_n,"delta24":delta}
        self.breadth_cache[key]=q
        print("BREADTH",b,align,universe_kind,
              "NOW",round(now_up,2) if now_up is not None else None,"N",now_n,
              "PREV",round(prev_up,2) if prev_up is not None else None,"N",prev_n,
              "DELTA",round(delta,2) if delta is not None else None,flush=True)
        return q

MKT=Market60()
if not (700 <= len(MKT.universe) <= 850):
    print("WARNING unusual CURRENT alt universe count",len(MKT.universe),flush=True)
if not (540 <= len(MKT.hist_universe) <= 620):
    raise SystemExit(
        "HISTORICAL JAN-AUG CACHE UNIVERSE AUDIT FAIL: "
        f"alt_symbols={len(MKT.hist_universe)}. "
        "Dynamic C6 must not substitute the current October universe."
    )


# ------------------------------------------------------------------
# RECOVERED ORIGINAL JAN-AUG C6 MARKET METRICS
# Source recovered from /root/.bash_history (2026-10-02 research run).
# IMPORTANT differences from earlier reconstructions:
#   * monthly cache file must cover warm_start -> month_end in ONE file
#   * R24 is close / close.shift(24), i.e. 24 observed rows
#   * POS24 is rolling(24, min_periods=20) on observed rows
#   * market delta24 is grouped UP24.shift(24), also 24 observed rows
#   * candidate sees only rows whose available_time = candle ts + 1h
# These details explain the one-trade ZEREBRO mismatch.
# ------------------------------------------------------------------
class RecoveredJanAugC6Metrics:
    def __init__(self):
        self.cache=R/".janaug_hist_cache_v1"
        pat=re.compile(r"^(?P<sym>.+)_60_(?P<s>\d{10})_(?P<e>\d{10})\.csv\.gz$")
        rows=[]
        for p in self.cache.glob("*_60_*.csv.gz"):
            m=pat.match(p.name)
            if not m:
                continue
            try:
                rows.append({
                    "symbol":m.group("sym"),"path":p,
                    "start":pd.to_datetime(m.group("s"),format="%Y%m%d%H",utc=True),
                    "end":pd.to_datetime(m.group("e"),format="%Y%m%d%H",utc=True),
                })
            except Exception:
                pass
        self.F=pd.DataFrame(rows)
        self.market={}
        self.symbol={}
        self.month_meta={}
        self._build()

    def _build(self):
        for month in range(1,9):
            ms=pd.Timestamp(f"2026-{month:02d}-01",tz=KST).tz_convert("UTC")
            me=(pd.Timestamp("2026-09-01",tz=KST) if month==8 else
                pd.Timestamp(f"2026-{month+1:02d}-01",tz=KST)).tz_convert("UTC")
            warm=ms-pd.Timedelta(hours=30)
            q=self.F[
                (self.F.start<=warm)&(self.F.end>=me)&
                (~self.F.symbol.isin(["BTCUSDT","ETHUSDT"]))
            ].sort_values(["symbol","start"]).drop_duplicates("symbol",keep="last")

            ls=[]
            for r in q.itertuples(index=False):
                try:
                    d=pd.read_csv(
                        r.path,usecols=["start_time","high","low","close"],
                        compression="gzip",low_memory=False
                    )
                    d["ts"]=pd.to_datetime(d.start_time,utc=True,errors="coerce")
                    for c in ["high","low","close"]:
                        d[c]=pd.to_numeric(d[c],errors="coerce")
                    d=d[(d.ts>=warm)&(d.ts<me)].dropna().sort_values("ts")
                    if len(d)<30:
                        continue
                    d["r24"]=(d.close/d.close.shift(24)-1)*100
                    hi=d.high.rolling(24,min_periods=20).max()
                    lo=d.low.rolling(24,min_periods=20).min()
                    d["pos24"]=(d.close-lo)/(hi-lo).replace(0,float("nan"))
                    d["symbol"]=str(r.symbol)
                    d["available_time"]=d.ts+pd.Timedelta(hours=1)
                    ls.append(d[["ts","available_time","symbol","r24","pos24"]])
                except Exception:
                    pass
            if not ls:
                raise SystemExit(f"RECOVERED C6 CACHE BUILD FAIL month={month:02d}")

            L=pd.concat(ls,ignore_index=True)
            B=L.groupby("ts").agg(
                up24=("r24",lambda s:100*(s>0).mean())
            ).reset_index().sort_values("ts")
            B["delta24"]=B.up24-B.up24.shift(24)
            B["available_time"]=B.ts+pd.Timedelta(hours=1)

            self.market[month]={
                "t":pd.to_datetime(B.available_time,utc=True).astype("int64").to_numpy(),
                "up24":B.up24.to_numpy(),
                "delta24":B.delta24.to_numpy(),
            }
            for sym,g in L.groupby("symbol"):
                g=g.sort_values("available_time")
                self.symbol[(month,str(sym))]={
                    "t":pd.to_datetime(g.available_time,utc=True).astype("int64").to_numpy(),
                    "r24":g.r24.to_numpy(),
                    "pos24":g.pos24.to_numpy(),
                }
            self.month_meta[month]={"symbols":int(L.symbol.nunique()),"rows":int(len(L))}
            print(f"[RECOVERED C6 {month:02d}] symbols={L.symbol.nunique()} rows={len(L)}",flush=True)

    def lookup(self,sym,t):
        t=pd.Timestamp(t)
        if t.tzinfo is None:
            t=t.tz_localize("UTC")
        else:
            t=t.tz_convert("UTC")
        month=int(t.tz_convert(KST).month)
        if month not in self.market:
            return None
        tv=t.value
        m=self.market[month]
        i=int(__import__('numpy').searchsorted(m["t"],tv,side="right")-1)
        s=self.symbol.get((month,str(sym)))
        if i<0 or s is None:
            return None
        j=int(__import__('numpy').searchsorted(s["t"],tv,side="right")-1)
        if j<0:
            return None
        return {
            "up24":fv(m["up24"][i]),
            "delta24":fv(m["delta24"][i]),
            "r24":fv(s["r24"][j]),
            "pos24":fv(s["pos24"][j]),
            "source":"RECOVERED_ORIGINAL_JA_ROW_SHIFT24",
        }

