def pre_c6_rows(trades):
    prev={}
    out=[]
    for r in trades.sort_values("entry_dt").to_dict("records"):
        sym=r["symbol"]; p=prev.get(sym)
        meta=day_meta.get(str(r["day"]),{})
        if p is not None:
            gap=(pd.Timestamp(r["entry_dt"])-pd.Timestamp(p["entry_dt"])).total_seconds()/3600
            if (p["result"]=="TP20_FULL" and gap>6 and gap<=24
                and int(meta.get("breadth",999))<=20
                and int(meta.get("streak",999)) in (1,2)):
                q=dict(r); q["prev_setup_id"]=p["setup_id"]; q["gap_h"]=gap
                q["breadth"]=meta.get("breadth"); q["streak"]=meta.get("streak")
                out.append(q)
        prev[sym]=r
    return pd.DataFrame(out)

