# ------------------------------------------------------------------
# Dynamic exact scheduler.
# ------------------------------------------------------------------
def run_dynamic(d,period,use_c7=False,use_c8=False):
    sched=U.Scheduler()
    trades=[]
    blocks=[]
    last_accepted={}
    missing_c7=set(); missing_c8=set()

    for _,r in d.iterrows():
        if not pre(r,period) or blocked(r,period):
            continue

        sid=str(r["setup_id"]); sym=str(r["symbol"])
        now=pd.Timestamp(r["_dt"]).to_pydatetime() if period=="JA" else r["_dt"]
        nowp=pd.Timestamp(now)
        day=str(r["entry_time_kst"])[:10]
        month=str(r["entry_time_kst"])[:7]
        ep=float(r["entry_price"])

        # Only evaluate guards when scheduler would currently allow entry.
        ok,_=sched.can_open(now,sym)
        if not ok:
            continue

        # DYNAMIC C6
        prior=last_accepted.get(sym)
        c6hit=False
        c6meta={}
        dm=day_meta.get(day,{})
        if prior is not None:
            gh=(nowp-pd.Timestamp(prior["entry_dt"])).total_seconds()/3600
            if (prior["result"]=="TP20_FULL" and gh>6 and gh<=24
                and int(dm.get("breadth",999))<=20
                and int(dm.get("streak",999)) in (1,2)):
                if period=="JA":
                    q=JA_RECOVERED.lookup(sym,nowp)
                    if (q and q.get("delta24") is not None and q["delta24"]<=-5
                        and q.get("r24") is not None and q["r24"]>=15
                        and q.get("pos24") is not None and q["pos24"]>=0.85):
                        c6hit=True
                        c6meta={
                            "prev_setup_id":prior["setup_id"],
                            "prev_result":prior["result"],
                            "gap_h":gh,
                            "breadth":dm.get("breadth"),
                            "low20_streak":dm.get("streak"),
                            **q,
                        }
                else:
                    sm=MKT.symbol_metrics(sym,nowp,ep,"close_prev")
                    if sm and sm["r24"]>=15 and sm["pos24"]>=0.85:
                        bm=MKT.true_breadth(nowp,"prev","current")
                        if bm.get("delta24") is not None and bm["delta24"]<=-5:
                            c6hit=True
                            c6meta={
                                "prev_setup_id":prior["setup_id"],
                                "prev_result":prior["result"],
                                "gap_h":gh,
                                "breadth":dm.get("breadth"),
                                "low20_streak":dm.get("streak"),
                                **sm,**bm,
                                "source":"SEP_CURRENT_TRADING_COMPLETED_1H",
                            }
        if c6hit:
            # Outcome is logged for analysis only; it is not added to scheduler.
            try:
                s0=getsim(r,period)
                oresult=str(s0.result); onet=float(s0.net_pct)
            except Exception:
                oresult=""; onet=float("nan")
            blocks.append({
                "period":period,"setup_id":sid,"symbol":sym,"entry_dt":nowp,
                "month":month,"guard":"C6","underlying_result":oresult,
                "underlying_net":onet,**c6meta
            })
            continue

        # C7
        ci=c7_info(sid)
        if use_c7 and not ci["complete"]:
            missing_c7.add(sid)
        if use_c7 and ci["hit"]:
            try:
                s0=getsim(r,period); oresult=str(s0.result); onet=float(s0.net_pct)
            except Exception:
                oresult=""; onet=float("nan")
            blocks.append({
                "period":period,"setup_id":sid,"symbol":sym,"entry_dt":nowp,
                "month":month,"guard":"C7","underlying_result":oresult,
                "underlying_net":onet,**ci
            })
            continue

        # C8A
        ei=c8_info(sid)
        if use_c8 and not ei["complete"]:
            missing_c8.add(sid)
        if use_c8 and ei["hit"]:
            try:
                s0=getsim(r,period); oresult=str(s0.result); onet=float(s0.net_pct)
            except Exception:
                oresult=""; onet=float("nan")
            blocks.append({
                "period":period,"setup_id":sid,"symbol":sym,"entry_dt":nowp,
                "month":month,"guard":"C8A","underlying_result":oresult,
                "underlying_net":onet,**ei
            })
            continue

        s=getsim(r,period)
        sched.add(now,sym,s,s.result in ("STOP","LATE_FAILURE_EXIT"))
        rec={
            "period":period,"setup_id":sid,"symbol":sym,"entry_dt":nowp,
            "day":day,"month":month,"result":str(s.result),"net_pct":float(s.net_pct),
        }
        trades.append(rec)
        last_accepted[sym]=rec

    return pd.DataFrame(trades),pd.DataFrame(blocks),missing_c7,missing_c8

def both(use_c7=False,use_c8=False):
    a,ba,m7a,m8a=run_dynamic(ja,"JA",use_c7,use_c8)
    b,bb,m7b,m8b=run_dynamic(se,"SE",use_c7,use_c8)
    return (
        pd.concat([a,b],ignore_index=True),
        pd.concat([ba,bb],ignore_index=True),
        m7a|m7b,m8a|m8b,
    )

def summary(x,label):
    rows=[]
    for m in [f"2026-{i:02d}" for i in range(1,10)]:
        g=x[x.month==m]
        rc=Counter(g.result.astype(str))
        rows.append({
            "scenario":label,"month":m,"N":len(g),
            "TP":rc["TP20_FULL"],"STOP":rc["STOP"],
            "PP":rc["PROFIT_PROTECT_EXIT"],"LATE":rc["LATE_FAILURE_EXIT"],
            "NET":float(g.net_pct.sum()),
        })
    return pd.DataFrame(rows)

