# Path-change ledgers between successive scenarios.
def path_changes(a,b,label):
    ka=set(a.setup_id.astype(str)); kb=set(b.setup_id.astype(str))
    rem=a[a.setup_id.astype(str).isin(ka-kb)].copy()
    add=b[b.setup_id.astype(str).isin(kb-ka)].copy()
    rem["change"]="REMOVED"; add["change"]="ADDED"
    z=pd.concat([rem,add],ignore_index=True)
    z["compare"]=label
    return z

